use verus::prelude::*;

/// The `intersperse` function takes a slice of `i32` and a
/// delimiter `delim`, and returns a `Vec<i32>` that
/// has the `delim` inserted between every two successive
/// elements of `numbers`.
#[requires(true)]
// If `numbers` is empty, the result is empty; otherwise
// its length is `2 * numbers.len() - 1`.
#[ensures(
    result.len() ==
        if numbers.len() == 0 {
            0
        } else {
            2 * numbers.len() - 1
        }
)]
// For each original index i, the element at 2*i in the result
// equals numbers[i].
#[ensures(
    forall(|i: usize| i < numbers.len() ==>
        result[2*i] == numbers[i]
    )
)]
// For each gap j (0 <= j+1 < numbers.len()), the result at
// position 2*j+1 is exactly the delimiter.
#[ensures(
    forall(|j: usize| j + 1 < numbers.len() ==>
        result[2*j + 1] == delim
    )
)]
pub fn intersperse(numbers: &[i32], delim: i32) -> Vec<i32> {
    let n = numbers.len();
    if n == 0 {
        return Vec::new();
    }
    // We will have exactly 2n - 1 elements in the result.
    let mut res = Vec::with_capacity(2 * n - 1);

    // Push the first element, then for each remaining element push the delimiter
    // and then the element itself.
    let mut iter = numbers.iter();
    if let Some(&first) = iter.next() {
        res.push(first);
        for &x in iter {
            res.push(delim);
            res.push(x);
        }
    }

    res
}

